# Generates the PAC file and the two LaunchAgent plists. Sourced by install.sh.

xml() { printf '%s' "$1" | sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g'; }

write_pac() {
    local list relayed
    list="$(domains | sed 's/.*/"&"/' | paste -sd, -)"
    relayed="$(printf '%s\n' $RELAY_HOSTS | sed 's/.*/"&"/' | paste -sd, -)"
    cat <<PAC
// Generated by discord-dpi. Discord domains go through the local bypass,
// everything else connects directly. Relayed names already point at the
// local relay through /etc/hosts, so they connect directly too.
var domains = [$list];
var relayed = [$relayed];
function FindProxyForURL(url, host) {
    host = host.toLowerCase();
    for (var j = 0; j < relayed.length; j++) {
        if (host == relayed[j]) return "DIRECT";
    }
    for (var i = 0; i < domains.length; i++) {
        if (host == domains[i] || dnsDomainIs(host, "." + domains[i])) {
            return "SOCKS5 127.0.0.1:$SOCKS_PORT; SOCKS 127.0.0.1:$SOCKS_PORT; DIRECT";
        }
    }
    return "DIRECT";
}
PAC
}

# Args: the full ciadpi command line, program path first.
write_proxy_plist() {
    local a
    cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$LABEL_PROXY</string>
    <key>ProgramArguments</key>
    <array>
EOF
    for a in "$@"; do printf '        <string>%s</string>\n' "$(xml "$a")"; done
    cat <<EOF
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
    <!-- ciadpi ignores SIGTERM on macOS, so don't wait the default 20s before SIGKILL. -->
    <key>ExitTimeOut</key>
    <integer>1</integer>
    <key>StandardOutPath</key>
    <string>$(xml "$LOG_FILE")</string>
    <key>StandardErrorPath</key>
    <string>$(xml "$LOG_FILE")</string>
</dict>
</plist>
EOF
}

# System daemon, because only root can listen on port 443. launchd opens the
# port as root and runs relay.sh as the given user, once per connection.
# Every relayed name uses the first one's address: they are all served from
# the same Discord front end, which picks the site by the name in the handshake.
# Args: <user name>
write_relay_plist() {
    local a args=(/bin/bash "$INSTALL_DIR/relay.sh" "${RELAY_HOSTS%% *}" "$SOCKS_PORT" "$DNS_PORT")
    # shellcheck disable=SC2206
    args+=($DNS_SERVERS)
    cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$LABEL_RELAY</string>
    <key>UserName</key>
    <string>$(xml "$1")</string>
    <key>ProgramArguments</key>
    <array>
EOF
    for a in "${args[@]}"; do printf '        <string>%s</string>\n' "$(xml "$a")"; done
    cat <<EOF
    </array>
    <key>inetdCompatibility</key>
    <dict>
        <key>Wait</key>
        <false/>
    </dict>
    <key>Sockets</key>
    <dict>
        <key>IPv4</key>
        <dict>
            <key>SockNodeName</key>
            <string>127.0.0.1</string>
            <key>SockServiceName</key>
            <string>443</string>
        </dict>
        <key>IPv6</key>
        <dict>
            <key>SockNodeName</key>
            <string>::1</string>
            <key>SockServiceName</key>
            <string>443</string>
            <key>SockFamily</key>
            <string>IPv6</string>
        </dict>
    </dict>
</dict>
</plist>
EOF
}

# launchd holds the port and starts pac-server.sh once per connection.
write_pac_plist() {
    cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$LABEL_PAC</string>
    <key>ProgramArguments</key>
    <array>
        <string>/bin/bash</string>
        <string>$(xml "$INSTALL_DIR/pac-server.sh")</string>
    </array>
    <key>inetdCompatibility</key>
    <dict>
        <key>Wait</key>
        <false/>
    </dict>
    <key>Sockets</key>
    <dict>
        <key>Listeners</key>
        <dict>
            <key>SockNodeName</key>
            <string>127.0.0.1</string>
            <key>SockServiceName</key>
            <string>$PAC_PORT</string>
            <key>SockType</key>
            <string>stream</string>
        </dict>
    </dict>
</dict>
</plist>
EOF
}
